const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var aoi = ee.Geometry.Point([-112.074, 33.4484]).buffer(20000); // Phoenix downtown, 20 km buffer
    var start = '2017-06-15';
    var end = '2017-06-22'; // end is exclusive

    // Helper to build collection, band, and conversion to Fahrenheit
    function getSource(primary) {
      if (primary) {
        var col = ee.ImageCollection('IDAHO_EPSCOR/GRIDMET')
          .filterDate(start, end)
          .select('tmmx');
        return {id: 'GRIDMET:tmmx', col: col, band: 'tmmx', scale: 4000, toF: function(img){ return img.subtract(273.15).multiply(9/5).add(32).rename('F'); }};
      } else {
        var col = ee.ImageCollection('NASA/ORNL/DAYMET_V4')
          .filterDate(start, end)
          .select('tmax');
        return {id: 'DAYMET:tmax', col: col, band: 'tmax', scale: 1000, toF: function(img){ return img.multiply(9/5).add(32).rename('F'); }}; // Daymet tmax in C
      }
    }

    // 2. Data Acquisition & Check
    var src = getSource(true);
    var size = await new Promise((resolve, reject) => src.col.size().getInfo((v, e) => e ? reject(e) : resolve(v)));
    if (size === 0) {
      var fallback = getSource(false);
      var fsize = await new Promise((resolve, reject) => fallback.col.size().getInfo((v, e) => e ? reject(e) : resolve(v)));
      if (fsize === 0) {
        console.log('Images (GRIDMET): 0');
        console.log('Images (DAYMET): 0');
        console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
        console.log('C1');
        return;
      } else {
        src = fallback;
        size = fsize;
        console.log(`Dataset: ${src.id}, Images: ${size}`);
      }
    } else {
      console.log(`Dataset: ${src.id}, Images: ${size}`);
    }

    // 3. Processing: per-day AOI max Fahrenheit and valid pixel count
    var fc = src.col.map(function(img) {
      var f = src.toF(img.select(src.band));
      var stats = f.reduceRegion({
        reducer: ee.Reducer.max().combine(ee.Reducer.count(), '', true),
        geometry: aoi,
        scale: src.scale,
        maxPixels: 1e9,
        bestEffort: true
      });
      var maxF = ee.Algorithms.If(stats.get('F_max'), stats.get('F_max'), null);
      var cnt = ee.Algorithms.If(stats.get('F_count'), stats.get('F_count'), 0);
      return ee.Feature(null, {
        date: img.date().format('YYYY-MM-dd'),
        maxF: maxF,
        count: cnt
      });
    });

    var results = await new Promise((resolve, reject) => fc.aggregate_array('date').evaluate(async (dates, err) => {
      if (err) return reject(err);
      try {
        var maxFs = await new Promise((res, rej) => fc.aggregate_array('maxF').evaluate((v,e)=> e?rej(e):res(v)));
        var counts = await new Promise((res, rej) => fc.aggregate_array('count').evaluate((v,e)=> e?rej(e):res(v)));
        resolve({dates, maxFs, counts});
      } catch(e) { reject(e); }
    }));

    // 4. Validation & Final Answer
    if (!results || !results.dates || results.dates.length === 0) {
      console.log('No features produced.');
      console.log('C3: Calculation Failure (Result is None/NaN or invalid).');
      console.log('C3');
      return;
    }

    var allNull = true, anyValidPixels = false, anyGE110 = false, lines = [];
    for (var i = 0; i < results.dates.length; i++) {
      var d = results.dates[i];
      var v = results.maxFs[i];
      var c = results.counts[i] || 0;
      var valStr = (v === null || v === undefined || Number.isNaN(v)) ? 'null' : v.toFixed(1);
      lines.push(`${d} MaxF: ${valStr}, Pixels: ${c}`);
      if (c > 0) anyValidPixels = true;
      if (v !== null && v !== undefined && !Number.isNaN(v)) {
        allNull = false;
        if (v >= 110) anyGE110 = true;
      }
    }

    // Print concise evidence lines
    lines.forEach(l => console.log(l));
    var daysGE = results.maxFs.filter(v => (v !== null && v !== undefined && !Number.isNaN(v) && v >= 110)).length;
    console.log(`Days >=110F: ${daysGE}`);

    if (!anyValidPixels) {
      console.log('C2: No Valid Pixels (Images exist, but after processing, 0 pixels remain).');
      console.log('C2');
      return;
    }
    if (allNull) {
      console.log('C3: Calculation Failure (Result is None/NaN or invalid).');
      console.log('C3');
      return;
    }

    // Final tag
    if (anyGE110) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }

  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
